  AND c.subject_id = 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a22'
  AND qq.type = 'multiple_choice';

-- Update Social Science MCQ questions (subject_id = 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a33')
